def keep_tracking_start_behavior(apps, schema_editor):
    """The removed 'tracking start' date skipped planned payroll before it; start those appointments on that date instead."""
    Worktag = apps.get_model("ledger", "Worktag")
    Appointment = apps.get_model("ledger", "Appointment")
    for worktag in Worktag.objects.exclude(tracking_start=None):
        Appointment.objects.filter(
            worktag=worktag, start_date__lt=worktag.tracking_start, end_date__gte=worktag.tracking_start
        ).update(start_date=worktag.tracking_start)


def convert_funds(apps, schema_editor):
    Worktag = apps.get_model("ledger", "Worktag")
    BudgetLine = apps.get_model("ledger", "BudgetLine")
    Funding = apps.get_model("ledger", "Funding")
    # Cost centers, projects and programs become foundation/gift funds: nothing lapses unless you switch a fund to State.
    Worktag.objects.filter(type__in=["cost_center", "project", "program"]).update(type="gift")
    # The old budget total becomes the fund's first funding entry.
    for worktag in Worktag.objects.all():
        lines = list(BudgetLine.objects.filter(worktag=worktag).values_list("amount", flat=True))
        if lines and not Funding.objects.filter(worktag=worktag).exists():
            Funding.objects.create(
                worktag=worktag,
                amount=sum(lines),
                date=worktag.start_date or worktag.created_at.date(),
                description="Budget total (carried over)",
            )


def add_meals_category(apps, schema_editor):
    Category = apps.get_model("ledger", "Category")
    CategoryRule = apps.get_model("ledger", "CategoryRule")
    meals, _ = Category.objects.get_or_create(
        code="meals", defaults={"name": "Meals & hospitality", "fa_eligible": True, "sort_order": 65}
    )
    if not CategoryRule.objects.filter(category=meals).exists():
        CategoryRule.objects.create(
            keywords="catering, food, snacks, refreshments, coffee, lunch, dinner, breakfast, pizza, hospitality",
            category=meals,
            priority=45,
        )


